#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.17.1  -  Free music without any sign-up (Openverse)
#   * Create > Music > Free music: search Creative Commons songs, quick genre chips.
#   * No account, no key and no Vercel setting is needed: it works after the signer
#     is deployed. (Jamendo's own developer sign-up is no longer used.)
#   * No-Derivatives licences are never offered. The signer keeps answers for 10 minutes.
#   * Includes the Markdown Privacy Policy and Terms, updated for this music source.
# Run from the project root:   bash update_v1171_free_music.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="335685b41c269e97b5737b62d0eb096314cbf759e85c36f78ef892cd77f02e97"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/core/legal.dart ] || { echo "ERROR: v1.16.0 is not installed. Run update_v1160_signup_timeline_pins_qr.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
rm -f docs/privacy.html docs/terms.html lib/services/epidemic_service.dart lib/services/jamendo_service.dart
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.17.1 is in place."
echo ""
echo "Music needs NO setting. After you push, wait until Vercel has deployed the signer"
echo "(Deployments -> the top one says Ready), then check:"
echo "  <your signer address>/api/health   ->  it shows \"music\":true"
echo "You can delete EPIDEMIC_API_KEY and JAMENDO_CLIENT_ID in Vercel; they are not used."
exit 0
